const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, TableOfContents, HeadingLevel, BorderStyle,
  WidthType, ShadingType, PageNumber, Header, Footer
} = require("docx");

// ---- Brand palette ----
const INK = "2E2A28";        // espresso near-black (headings + body)
const ACCENT = "A8636F";     // muted mauve-rose
const ACCENT_DK = "7A4853";  // deeper mauve
const BLUSH = "F6ECEE";      // soft script-box fill
const RULE = "D8C4C9";       // light mauve rule
const GREY = "6E6864";       // muted caption grey

const CW = 9360; // content width DXA (US Letter, 1" margins)

// ---- Helpers ----
const C = [];

function h1(text) {
  C.push(new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(text)] }));
}
function h2(text) {
  C.push(new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(text)] }));
}
function h3(text) {
  C.push(new Paragraph({ heading: HeadingLevel.HEADING_3, children: [new TextRun(text)] }));
}
function p(text, opts = {}) {
  C.push(new Paragraph({
    spacing: { after: 140, line: 276 },
    children: [new TextRun({ text, ...opts })]
  }));
}
// rich paragraph: runs = array of {text, bold, italics, color}
function pr(runs, opts = {}) {
  C.push(new Paragraph({
    spacing: { after: 140, line: 276 },
    children: runs.map(r => new TextRun(r)),
    ...opts
  }));
}
function bullet(text, ref = "bullets") {
  C.push(new Paragraph({
    numbering: { reference: ref, level: 0 },
    spacing: { after: 80, line: 270 },
    children: [new TextRun(text)]
  }));
}
function bulletRich(runs, ref = "bullets") {
  C.push(new Paragraph({
    numbering: { reference: ref, level: 0 },
    spacing: { after: 80, line: 270 },
    children: runs.map(r => new TextRun(r))
  }));
}
function num(text, ref) {
  C.push(new Paragraph({
    numbering: { reference: ref, level: 0 },
    spacing: { after: 80, line: 270 },
    children: [new TextRun(text)]
  }));
}
function spacer() {
  C.push(new Paragraph({ spacing: { after: 60 }, children: [new TextRun("")] }));
}

// A small label line above a script box, e.g. "SAY" or "TEXT"
function microLabel(label) {
  C.push(new Paragraph({
    spacing: { before: 60, after: 30 },
    children: [new TextRun({ text: label.toUpperCase(), bold: true, size: 16, color: ACCENT_DK, characterSpacing: 30 })]
  }));
}

// Script box: a single-cell shaded table with a left accent bar.
// lines = array of strings (each becomes a paragraph). Pass {speaker} option to bold a lead-in.
function scriptBox(lines) {
  const para = (line, i) =>
    new Paragraph({
      spacing: { after: i === lines.length - 1 ? 0 : 120, line: 280 },
      children: [new TextRun({ text: line, size: 22, color: INK })]
    });
  C.push(new Table({
    width: { size: CW, type: WidthType.DXA },
    columnWidths: [CW],
    rows: [new TableRow({
      children: [new TableCell({
        width: { size: CW, type: WidthType.DXA },
        shading: { fill: BLUSH, type: ShadingType.CLEAR, color: "auto" },
        margins: { top: 140, bottom: 140, left: 220, right: 200 },
        borders: {
          top: { style: BorderStyle.SINGLE, size: 2, color: BLUSH },
          bottom: { style: BorderStyle.SINGLE, size: 2, color: BLUSH },
          right: { style: BorderStyle.SINGLE, size: 2, color: BLUSH },
          left: { style: BorderStyle.SINGLE, size: 24, color: ACCENT }
        },
        children: lines.map(para)
      })]
    })]
  }));
  C.push(new Paragraph({ spacing: { after: 120 }, children: [new TextRun("")] }));
}

// "Why this works" note
function why(text) {
  C.push(new Paragraph({
    spacing: { after: 160, line: 270 },
    children: [
      new TextRun({ text: "Why this works:  ", bold: true, color: ACCENT_DK, size: 21 }),
      new TextRun({ text, italics: true, size: 21, color: INK })
    ]
  }));
}

// Section divider rule
function rule() {
  C.push(new Paragraph({
    spacing: { before: 120, after: 160 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: RULE, space: 1 } },
    children: [new TextRun("")]
  }));
}

module.exports = {
  C, h1, h2, h3, p, pr, bullet, bulletRich, num, spacer, microLabel,
  scriptBox, why, rule,
  INK, ACCENT, ACCENT_DK, BLUSH, RULE, GREY, CW,
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, TableOfContents, HeadingLevel, BorderStyle,
  WidthType, ShadingType, PageNumber, Header, Footer, fs
};

