const B = require("./build.js");
const {
  C, h1, h2, h3, p, pr, bullet, bulletRich, num, spacer, microLabel,
  scriptBox, why, rule,
  INK, ACCENT, ACCENT_DK, BLUSH, RULE, GREY, CW,
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, TableOfContents, HeadingLevel, BorderStyle,
  WidthType, ShadingType, PageNumber, Header, Footer, fs
} = B;

// ============ TITLE BLOCK (no page break per brand rule) ============
C.push(new Paragraph({
  spacing: { before: 80, after: 40 },
  children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 22, color: ACCENT_DK, characterSpacing: 60 })]
}));
C.push(new Paragraph({
  spacing: { after: 60 },
  children: [new TextRun({ text: "The Conversion Playbook", bold: true, size: 52, color: INK })]
}));
C.push(new Paragraph({
  spacing: { after: 120 },
  children: [new TextRun({ text: "Client-Facing Sales and Consultation Scripts for Every Role and Every Touchpoint", size: 26, color: INK })]
}));
C.push(new Paragraph({
  border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: ACCENT, space: 2 } },
  spacing: { after: 160 },
  children: [new TextRun({ text: "Front Desk  \u00B7  Patient Coordinators  \u00B7  Nurse Practitioners and Injectors  \u00B7  Estheticians  \u00B7  Check-Out", size: 20, color: GREY })]
}));
C.push(new Paragraph({
  spacing: { after: 200 },
  children: [new TextRun({ text: "The spa you imagined is still in there. So are you.", italics: true, size: 22, color: ACCENT_DK })]
}));

// ============ HOW TO USE ============
h1("How To Use This Playbook");
p("This playbook is the single source of truth for every conversation that touches a patient inside your med spa. It is written for the whole team, not just one person. The front desk uses it to turn a cold inquiry into a booked consultation. The coordinator and provider use it to turn a consultation into a treatment plan, a membership, or a package. The esthetician uses it to turn a single facial into a series. Check-out uses it to make rebooking the default rather than the exception.");
p("Every script in this document is written the way a real person speaks, with natural contractions, so your team can read it once and make it their own. The instructions and coaching around each script are written in plain language. Nothing here is meant to be read off a card in front of a patient. The goal is for your team to internalize the structure, then sound like themselves.");

h3("The four things every client-facing team member must remember");
bulletRich([{ text: "Diagnose before you prescribe. ", bold: true }, { text: "Nobody buys a plan they did not help build. Ask first, listen fully, then recommend." }]);
bulletRich([{ text: "Lead with the outcome, not the product. ", bold: true }, { text: "Patients do not want units of neurotoxin or a laser pass. They want to look rested, feel confident, and stop hiding in photos. Sell that." }]);
bulletRich([{ text: "Always present the smart financial choice. ", bold: true }, { text: "The single treatment is almost never the best value. Membership and packages save the patient money and get them better results. Framing them as the generous option is honest, not pushy." }]);
bulletRich([{ text: "The next appointment is booked before they leave. ", bold: true }, { text: "A patient who walks out without a future booking is a revenue leak. Closing the loop is everyone's job." }]);

rule();

// ============ THE PHILOSOPHY ============
h1("The Luxora Sales Philosophy");
p("Most med spa teams were never taught to sell. They were taught to be clinical, kind, and careful, which patients love, and which is also why so much revenue walks out the door unbooked. Selling well in aesthetics is not about pressure. It is about confidence, clarity, and care. A patient who trusts you wants you to tell them what will actually get them the result they came in for.");

h3("Consultative, never pushy");
p("Pressure closes one sale and loses the patient. Consultation closes the patient for years. Every script here is built on a simple arc: connect, understand, recommend, and make it easy to say yes. When a patient feels understood, price becomes a detail rather than a wall.");

h3("Value over discount");
p("Discounting trains patients to wait for the next sale and quietly erodes your margins. Luxora teams do not lead with discounts. They lead with value: better results from a plan, real savings from a membership, and the confidence of a provider who has a point of view. When you must move on price, you right-size the plan rather than slash the rate.");

h3("Lifetime value is the whole game");
p("A new patient is not worth the price of their first treatment. They are worth every visit, every product, and every referral over the years they stay with you. That is why the membership conversation and the rebooking conversation matter more than any single transaction. Your team is not closing a sale. They are opening a relationship.");

rule();

// ============ SECTION 1: FRONT DESK ============
h1("Section 1: Front Desk and Patient Coordinator");
p("The front desk is the most underused revenue position in the building. This is the first human voice a cold lead hears and the last one a patient hears before they leave. Two conversations decide more revenue than any ad: how the phone gets answered, and how check-out is handled. This section gives your front desk the language to convert inquiries into booked consultations, protect the schedule from no-shows, and make rebooking automatic.");

h2("1.1  Inbound Phone Inquiry (Cold Lead to Booked Consultation)");
p("A cold caller is rarely shopping for information. They are shopping for a reason to trust you. The mistake most front desks make is answering the question and hanging up. The goal of every inbound call is one thing: a booked appointment with a name, a number, and a confirmed time.");

h3("The opening");
microLabel("Say");
scriptBox([
  "Thank you for calling [Spa Name], this is [Name]. How can I help you feel amazing today?"
]);
why("A warm, branded greeting signals premium positioning in the first three seconds and sets a tone that this is a place that takes care of people. It also gives the caller permission to share a goal rather than just a question.");

h3("When they ask about a specific treatment or price");
p("Do not quote a flat price and stop. Bridge to the consultation, because the consultation is where the real recommendation and the real sale happen.");
microLabel("Say");
scriptBox([
  "Great question. The honest answer is that it depends on what you're trying to achieve, and I'd hate to quote you something that isn't right for you. That's exactly what the consultation is for. You'll sit down with one of our providers, they'll look at your skin, listen to your goals, and build a plan that fits. The consultation is [free / $X and applied to your first treatment]. I have an opening [day] at [time] or [day] at [time]. Which works better for you?"
]);
why("Offering two specific times rather than asking when they are free assumes the booking and makes saying yes the path of least resistance. Naming the consultation as the place where the plan gets built reframes price as premature rather than withheld.");

h3("When they hesitate or want to think about it");
microLabel("Say");
scriptBox([
  "Totally understand, there's no pressure at all. The consultation itself is the no-risk part. You'll get a real plan and a clear price, and you decide from there with zero obligation. Let's hold a spot so you have it, and you can always move it if you need to. Does [day] or [day] feel better?"
]);
why("Holding a spot lowers the stakes of committing while still capturing the booking. The promise of a clear plan and price with no obligation removes the fear that drives most hesitation on a first call.");

h3("Always capture the contact before you hang up");
microLabel("Say");
scriptBox([
  "Perfect. So I have everything ready for you, what's the best cell number and email to send your confirmation and a little welcome note to? And who can I thank for calling in today?"
]);
why("Capturing the cell and email turns a one-time caller into someone you can follow up with through your nurture sequence if they do not book, which recovers leads that would otherwise vanish.");

h2("1.2  Inbound DM, Text, or Form-Fill Response");
p("Speed wins online leads. A lead that fills out a form expects a near-instant reply, and every minute of delay lowers the chance they book. The first message should feel personal, move toward a time, and never read like an automated blast.");
microLabel("First reply (within 5 minutes)");
scriptBox([
  "Hi [First Name], it's [Name] from [Spa Name]. So glad you reached out about [treatment / goal they mentioned]. I'd love to get you in for a consultation so we can build the right plan for you. I have [day] at [time] or [day] at [time] open this week. Which one should I save for you?"
]);
microLabel("If no reply within a few hours");
scriptBox([
  "Hi [First Name], just want to make sure you didn't miss my note. I'd hate for you to lose the spot. Are you still hoping to come in this week, or would next week be easier?"
]);
why("Using their first name and referencing the specific goal they mentioned signals a human read their message. The follow-up frames the lost spot as the risk, which gently creates urgency without pressure.");

h2("1.3  Appointment Confirmation and No-Show Prevention");
p("Every no-show is a paid-for slot earning nothing. The confirmation is not a reminder, it is a value touch. A good confirmation re-sells the appointment, pre-frames the experience, and makes the patient feel expected.");
microLabel("Confirmation text (24 to 48 hours before)");
scriptBox([
  "Hi [First Name], we can't wait to see you [day] at [time] for your consultation at [Spa Name]. Your provider [Name] has time set aside just for you. Come with any questions and any goals on your mind, big or small. Reply C to confirm or call us if anything changes."
]);
why("Naming the provider and saying time is set aside personalizes the slot, which makes a no-show feel like standing up a person rather than canceling an entry in an app. Inviting goals primes the patient to arrive ready to engage rather than just browse.");

h2("1.4  The Welcome and Check-In");
p("The first ninety seconds in the building set the ceiling on what a patient will spend. Warmth, eye contact, and a sense of being expected raise trust before the provider ever walks in. The front desk is selling without selling here.");
microLabel("On arrival");
scriptBox([
  "You must be [First Name], welcome. We've been looking forward to having you in. Can I get you some water or a tea while you get comfortable? [Provider] is excited to meet you and is just finishing up. While you settle in, here's a quick look at the treatments we're loving right now."
]);
why("Being recognized by name and offered hospitality signals a premium experience that justifies premium pricing. Handing over a curated look at current treatments plants seeds the provider can harvest later in the consultation.");

h2("1.5  Check-Out and Rebooking");
p("Check-out is where most med spas leak the most money. A patient who just had a great experience is at peak trust and lowest resistance. This is the single best moment to book the next visit, and it must never be skipped.");
h3("The default rebooking question");
microLabel("Say");
scriptBox([
  "You're all set, and you're going to love how this settles in over the next couple of weeks. To keep your results looking their best, [Provider] recommends seeing you again in [X weeks]. Let's go ahead and get that on the calendar now so you get the time slot you want. Do mornings or afternoons work better for you?"
]);
why("Framing the next visit as the provider's recommendation gives it clinical authority, and asking mornings or afternoons assumes the booking rather than asking whether they want one. The scarcity of preferred time slots gives a gentle reason to book now.");

h3("If they say they will call to schedule later");
microLabel("Say");
scriptBox([
  "Totally fine, and I get it, life's busy. Here's the thing though, the spots people want go fast, and I'd hate for you to fall out of your ideal timing and lose some of these results. Let's pencil something in now, and you have my word it's easy to move if you need to. What does the same time in [X weeks] look like for you?"
]);
why("Acknowledging their reason first lowers defensiveness. The honest warning that delaying can cost results ties rebooking to the outcome they care about rather than to your schedule.");

h2("1.6  Membership Enrollment at the Desk");
p("The front desk should be fluent in the membership offer, because many patients decide at check-out once they have felt the experience. Keep it short, lead with savings and access, and make enrolling feel like the obvious next step.");
microLabel("Say");
scriptBox([
  "Quick thing before you go, since you loved today and you're already planning to come back, our membership would actually save you money on exactly what you just had. It's [$X a month], it covers [core benefit], and members get [perks: priority booking, member pricing, monthly credit]. Most people who come in regularly are better off on it from day one. Want me to set you up so today counts toward it?"
]);
why("Anchoring the membership to what they just bought and enjoyed makes the value concrete rather than abstract. Offering to apply today's visit toward it removes the feeling of starting over and rewards an immediate yes.");

h2("1.7  The Phone Price-Shopper");
p("Price-shoppers are not lost causes, they are simply comparing because no one has given them a reason not to. The job is to shift the conversation from price to fit and value, and to get them in the door where you win.");
microLabel("When they lead with what is your price for [treatment]");
scriptBox([
  "Happy to talk through that. Can I ask first, what are you hoping to fix or improve? The reason I ask is that the same treatment can be a great deal or a waste of money depending on whether it's the right one for you. I'd rather help you spend smart than just quote you a number. Tell me a little about what's going on, and I'll point you in the right direction."
]);
why("Refusing to compete on a number alone and pivoting to the patient's actual goal repositions your spa as an advisor rather than a vending machine. Patients who feel guided rather than sold rarely keep shopping.");

rule();
fs.writeFileSync("/tmp/partA.flag", "ok");
module.exports = {}; // content lives in shared B.C

