const B = require("./build.js");
const {
  h1, h2, h3, p, pr, bullet, bulletRich, num, spacer, microLabel,
  scriptBox, why, rule
} = B;

// ============ SECTION 5: MEMBERSHIP ============
h1("Section 5: Membership Conversion (All Roles)");
p("Membership is the single most important revenue lever in a modern med spa. It converts one-time buyers into predictable monthly revenue, raises lifetime value, and makes every other conversation easier because the patient is already committed to coming back. Every client-facing role should be able to present membership fluently in under thirty seconds. This section gives the team a shared language so the offer sounds consistent no matter who delivers it.");

h2("5.1  The Membership Story Your Team Must Believe");
p("Your team will only sell membership with conviction if they understand why it genuinely benefits the patient. Before any script, make sure everyone can answer the patient's silent question: what is in this for me?");
bulletRich([{ text: "It saves them money. ", bold: true }, { text: "A regular patient almost always spends less per year as a member than as a pay-as-you-go patient." }]);
bulletRich([{ text: "It gets them better results. ", bold: true }, { text: "Membership builds in the consistency that aesthetic results require, so members simply look better over time." }]);
bulletRich([{ text: "It removes friction. ", bold: true }, { text: "Priority booking, banked credits, and member pricing mean they never have to think about whether today is worth it." }]);
bulletRich([{ text: "It makes them feel taken care of. ", bold: true }, { text: "Membership is a relationship, not a transaction, and patients feel the difference." }]);

h2("5.2  The Universal Membership Pitch");
p("This is the core script any team member can use. It anchors to what the patient already wants, leads with savings and results, and ends with an easy yes that lets today count.");
microLabel("Say");
scriptBox([
  "Can I show you something that'll actually save you money? Since you're planning to come back anyway, our membership is built for exactly that. It's [$ a month]. That covers [core benefit], you get member pricing on everything else, and you get [priority booking and any perks]. When I do the math, most people who come in like you do end up paying less as a member than they would otherwise, and they get better results because they stay consistent. I can set it up right now so today's visit counts toward it. Want me to?"
]);
why("Opening with a promise to save the patient money reframes the entire pitch as a benefit rather than a request. Letting today's visit count toward the membership removes the psychological hurdle of starting over and rewards an immediate decision.");

h2("5.3  Membership Objection Handling");
h3("I am not sure I will come in enough to use it");
microLabel("Say");
scriptBox([
  "That's exactly why it's worth it. The membership is what makes sure you do come in, and consistency is the whole reason people get results. And your credits don't disappear, they bank for you, so you're never wasting it. Honestly, the people who say that are the ones who benefit most, because it keeps them on track."
]);
h3("I would rather just pay as I go");
microLabel("Say");
scriptBox([
  "Totally fair, and you absolutely can. Let me just show you the math though, because pay-as-you-go almost always costs more over a year for someone who comes in like you do. Same treatments, you'd just be paying full price each time instead of member pricing. If the numbers say membership saves you money, would you want me to set it up?"
]);
h3("Can I think about it");
microLabel("Say");
scriptBox([
  "Of course, no pressure at all. The only reason I'd set it up today is so this visit counts toward it and you start saving immediately rather than starting from zero next time. It's month to month, so you're never locked in. Want to start saving today, or would you rather we revisit it at your next visit?"
]);
why("Each response acknowledges the concern before answering, which keeps the patient from feeling resisted. Offering the math and the month-to-month flexibility removes the two fears, overpaying and being trapped, that drive almost every membership hesitation.");

rule();

// ============ SECTION 6: PACKAGES ============
h1("Section 6: Package and High-Ticket Conversion");
p("Packages move patients from buying a treatment to buying a transformation. They raise the average transaction, guarantee a course of visits, and deliver the results that create loyal, referring patients. The key to selling a package is to present it as the path to the outcome the patient already told you they want, with the savings as a bonus rather than the headline.");

h2("6.1  Package Talking Points");
bulletRich([{ text: "Sell the result, not the count. ", bold: true }, { text: "Patients do not want six sessions. They want clear skin or a lifted jawline. Lead with the outcome and let the session count be the means." }]);
bulletRich([{ text: "The package is the honest recommendation. ", bold: true }, { text: "If the result genuinely requires a course of treatments, then recommending a single session is the dishonest option, not the package." }]);
bulletRich([{ text: "Savings are the bonus, not the pitch. ", bold: true }, { text: "Mention the savings after the patient is sold on the result, as the reason to commit now rather than later." }]);

h2("6.2  Presenting A High-Ticket Package");
p("Anchor on the full result and what it takes to get there, then present the package as both the path and the better value. Confidence is everything here. A package presented with hesitation will be declined.");
microLabel("Say");
scriptBox([
  "So let's talk about actually getting you the result you came in for, not just a treatment that fades. For [their goal], the honest answer is it takes a course of [number] treatments spaced over [timeframe]. That's just what the skin needs, there's no shortcut. Now, you could book those one at a time, but that's the expensive way to do it. Our [package name] gives you the whole course, you save [$ amount] versus paying separately, and you lock in your spots so you actually finish and see the result. This is the one I'd recommend without hesitation."
]);
why("Stating that there is no shortcut to the result establishes the package as a clinical reality rather than an upsell. Contrasting the package with the expensive way of booking one at a time makes committing to the full course feel like the financially smart decision.");

h2("6.3  Financing And Payment Language");
p("Price resistance is often a cash-flow concern, not a value concern. Offering a payment path can turn a no into a yes without ever touching your price. Present financing as a convenience, calmly and without embarrassment.");
microLabel("Say");
scriptBox([
  "And if it's easier to spread this out, we've got you. A lot of our patients use [financing option] and break it into manageable monthly payments instead of all at once. It doesn't change the price at all, it just makes it comfortable. Want me to show you what that'd look like per month? Sometimes seeing it that way makes the decision a lot easier."
]);
why("Presenting financing as something many patients use normalizes it and removes any stigma the patient might feel. Reframing a large total as a comfortable monthly figure addresses the real barrier, which is usually cash flow rather than the value of the result.");

h2("6.4  Package Objection Handling");
h3("That is a lot of money up front");
microLabel("Say");
scriptBox([
  "I hear you, it's a real investment. Here's the way I'd think about it though. Booked separately, the same treatments would actually cost you more, you'd just be paying it in pieces and probably not finishing. The package saves you money and makes sure you get the result. And if up front is the issue, we can break it into payments. Would monthly make this easier for you?"
]);
h3("What if it does not work");
microLabel("Say");
scriptBox([
  "Great question, and I'd want to know that too. Here's the honest answer. A course of treatments is exactly how we make sure it works, because one session was never going to get you there. This protocol is what gets results for patients with [their concern]. We'll track your progress at every visit, and I'll be honest with you the whole way. You're not guessing, you're following a plan that works."
]);
why("Acknowledging the size of the investment before reframing it keeps the patient from feeling dismissed. Tying the package directly to the certainty of the result answers the unspoken fear behind every high-ticket objection, which is the fear of wasting money.");

rule();

// ============ SECTION 7: EXISTING PATIENT EXPANSION ============
h1("Section 7: Existing Patient Expansion");
p("Your existing patients are your most overlooked growth engine. They already trust you, they already buy, and they cost nothing to acquire. Yet most med spas treat every visit as a repeat of the last one rather than a chance to deepen the relationship. This section gives your team the language to expand existing patients into new services, memberships, larger packages, and referrals, all without ever feeling pushy with someone who already knows you.");

h2("7.1  The Expansion Mindset");
p("Expansion is not about extracting more from loyal patients. It is about making sure they know everything you can do for them. Many patients stay narrow simply because no one ever told them about the treatment that would change their life. Silence is not respect, it is a disservice.");

h2("7.2  Cross-Sell To An Existing Patient");
p("Anchor the new recommendation in the trust you have already earned and the results they have already seen. Connect the new service to a goal they have mentioned before.");
microLabel("Say");
scriptBox([
  "You've been one of my favorite patients to work with, and your [existing treatment] results are gorgeous. Because I know your skin so well now, I've actually been wanting to mention something. The next thing that would take you to a whole other level is [new treatment]. It targets [the thing they've mentioned wanting], which is the one piece we haven't touched yet. I really think you'd love the result. Can I tell you how it'd work for you?"
]);
why("Referencing the long relationship and the results they have already seen makes the new recommendation feel earned rather than opportunistic. Framing the new service as the one piece we have not touched yet presents expansion as completing their journey.");

h2("7.3  Upgrading A Pay-As-You-Go Patient To Membership");
p("Loyal non-members are leaving savings on the table and you are leaving predictable revenue on the table. Approach the conversation as doing them a favor you should have done sooner.");
microLabel("Say");
scriptBox([
  "Can I be honest about something? You come in regularly, you're basically already a member in everything but name, and you've been paying full price this whole time. I actually feel a little bad I haven't set you up sooner. If we put you on the membership, you'd get member pricing on everything you already do and you'd save real money this year. Let me fix that for you today. Sound good?"
]);
why("Framing the missed membership as something you feel bad about removes any sense of a sales motive and positions enrollment as correcting an oversight in the patient's favor. Patients who already buy regularly find this almost impossible to refuse because the savings are self-evident.");

h2("7.4  Upgrading To A VIP Or Annual Tier");
p("Your best patients often want to be recognized as your best patients. An annual or VIP tier rewards them while locking in a year of revenue. Present it as an invitation, not a sale.");
microLabel("Say");
scriptBox([
  "I want to let you in on something we don't offer to everyone. Because you're one of our most loyal patients, you'd be perfect for our [VIP / annual] tier. It's our best pricing, you get [premium perks], and you're first in line for everything. It's really our way of taking care of the patients who take care of us. Want me to tell you what's included?"
]);
why("Positioning the upgrade as something not offered to everyone makes it feel like recognition rather than an upsell, which appeals to a loyal patient's desire to be valued. Inviting them into a tier reserved for the best patients turns a transaction into a status they want to claim.");

h2("7.5  The Referral Ask");
p("Happy patients refer when you make it easy and give them a reason. The best time to ask is right after a great result, when their enthusiasm is highest. Be direct and warm, never apologetic.");
microLabel("Say");
scriptBox([
  "Okay, you look incredible, and I have to ask you a favor. The best compliment you can give me is sending me someone you love. If you've got a friend who's been wanting to do something for themselves, send them my way. I'll take amazing care of them, and I'll make sure you both get [referral perk] as a thank you. Who comes to mind?"
]);
why("Asking who comes to mind rather than whether they know anyone prompts the patient to actually picture specific people, which produces far more referrals. Tying the ask to a great result and a mutual reward makes referring feel generous to their friend rather than like doing the spa a favor.");

rule();

// ============ SECTION 8: REACTIVATION ============
h1("Section 8: Reactivation (Lapsed Patients)");
p("Every med spa has a quiet fortune sitting in its lapsed patient list. These are people who already trusted you, already paid you, and simply drifted away, usually because no one reached out. Reactivation is the highest-return outreach you can do, because the relationship already exists. This section gives your team warm, low-pressure language to bring lapsed patients back without sounding like a collections call.");

h2("8.1  The Win-Back Call");
p("Lead with genuine warmth and curiosity, not a pitch. The goal of the first contact is simply to reopen the door and remind them they are missed.");
microLabel("Say");
scriptBox([
  "Hi [First Name], it's [Name] from [Spa Name]. No agenda here, I was just going through our patients and your name came up, and I realized we haven't seen you in a while. We've genuinely missed you. How have you been? And is there anything that's been keeping you away that I can help with?"
]);
why("Opening with no agenda and we have missed you disarms the patient who expects to be sold and reframes the call as a relationship touch. Asking what has kept them away surfaces the real reason for the lapse so you can address it directly rather than guessing.");

h2("8.2  The Win-Back Text and Email");
p("For patients who do not answer the phone, a warm text or email reopens the door. Keep it personal, short, and focused on them rather than on a promotion.");
microLabel("Text");
scriptBox([
  "Hi [First Name], it's [Name] at [Spa Name]. We were just thinking about you, it's been a while and we'd love to get you back in. Is there a treatment you've been missing or curious about? I'd love to take care of you again."
]);
microLabel("Email subject line options");
scriptBox([
  "We've been thinking about you, [First Name]",
  "Your spot is still here whenever you're ready",
  "It's been too long, [First Name]"
]);
why("A message that centers the patient rather than a discount feels like a person reaching out instead of a marketing blast, which dramatically raises reply rates. Naming a specific treatment they might be missing reopens desire without leading with a promotion.");

h2("8.3  The Reactivation Offer");
p("Once the patient is re-engaged, a gentle, time-bound welcome-back offer removes the last bit of friction. Frame it as a gift for returning, not a desperate discount.");
microLabel("Say");
scriptBox([
  "Since it's been a while and I'd genuinely love to get you back in, I want to do something nice for you. Come in this month and I'll take care of you with [welcome-back offer]. It's just my way of saying I'm glad you're back. Should we find a time that works this week or next?"
]);
why("Presenting the offer as a personal gesture rather than a blanket discount preserves your pricing dignity while still lowering the barrier to return. The light time frame of this month creates a gentle reason to act now without applying real pressure.");

rule();

